def status_meaning(code):
    category = code // 100
    if category == 2:
        return 'success'
    if category == 3:
        return 'redirect'
    if category == 4:
        return 'client_error'
    if category == 5:
        return 'server_error'
    return 'unknown'

def parse_request(path_user_id, query):
    try:
        user_id = int(path_user_id)
    except (TypeError, ValueError):
        return {'error': 'invalid_path'}

    raw_limit = query.get('limit', 20)
    try:
        limit = int(raw_limit)
    except (TypeError, ValueError):
        return {'error': 'invalid_query'}
    if limit <= 0:
        return {'error': 'invalid_query'}

    return {'user_id': user_id, 'limit': limit}

def validate_create_user(body):
    name = body.get('name')
    if not isinstance(name, str) or not name.strip():
        return [False, {'field': 'name', 'code': 'required'}]

    email = body.get('email')
    if email is None:
        return [False, {'field': 'email', 'code': 'required'}]
    if not isinstance(email, str) or '@' not in email:
        return [False, {'field': 'email', 'code': 'invalid'}]

    active = body.get('active', True)
    if not isinstance(active, bool):
        return [False, {'field': 'active', 'code': 'invalid'}]

    return [True, {'name': name.strip(), 'email': email, 'active': active}]

def require_role(user, allowed_roles):
    role = user.get('role') if isinstance(user, dict) else None
    if role in allowed_roles:
        return [True, 200]
    return [False, 403]

def build_user_response(record):
    required = ('id', 'name', 'email')
    for key in required:
        if key not in record:
            return {'error': 'invalid_record'}
    return {
        'id': record['id'],
        'name': record['name'],
        'email': record['email'],
    }

