def register_route(router, method, path, handler):
    key = f'{method.upper()}:{path}'
    router[key] = handler
    return router

def match_route(router, method, path):
    key = f'{method.upper()}:{path}'
    return router.get(key)

def validate_request(body, required):
    for field in required:
        value = body.get(field)
        if value is None or (isinstance(value, str) and not value.strip()):
            return [False, {'field': field, 'code': 'required'}]
    return [True, body]

def build_response(data, status):
    return {'data': data, 'status': status, 'ok': status < 400}
